    return {
      format: FORMAT,
      schemaVersion: dataset.schemaVersion,
      version: dataset.version,
      source: dataset.source,
      generatedAt: dataset.generatedAt,
      installedAt: dataset.installedAt || null,
      dict,
      rows
    };
