  const REFERENCE_DESC = /\b(guides?|wikis?|indexe?s?|directory|directories|lists?|tutorials?|courses?|documentation|docs|forums?|subreddits?|communit(?:y|ies)|blogs?|news|charts?|comparisons?|rankings?)\b/i;

